        minX = data.optionalDouble("min_x"),
        maxY = data.optionalDouble("max_y"),
        minY = data.optionalDouble("min_y"),
    )

    "WORLD_MARKER_PLACED" -> WorldMarkerPlacedEvent(
        instanceId = data.optionalString("instance_id"),
        markerIndex = data.optionalLong("marker_index"),
        x = data.optionalDouble("x"),
        y = data.optionalDouble("y"),
    )

    "WORLD_MARKER_REMOVED" -> WorldMarkerRemovedEvent(
        instanceId = data.optionalString("instance_id"),
        markerIndex = data.optionalLong("marker_index"),
    )

    "COMBATANT_INFO" -> CombatantInfoEvent(
        playerGuid = data.optionalString("player_guid"),
        faction = data.optionalLong("faction"),
        strength = data.optionalLong("strength"),
        agility = data.optionalLong("agility"),
        stamina = data.optionalLong("stamina"),
        intellect = data.optionalLong("intellect"),
        unknown120 = data.optionalLong("unknown_12_0"),
        dodgeRating = data.optionalLong("dodge_rating"),
        parryRating = data.optionalLong("parry_rating"),
        blockRating = data.optionalLong("block_rating"),
        critRatingMelee = data.optionalLong("crit_rating_melee"),
        critRatingRanged = data.optionalLong("crit_rating_ranged"),
        critRatingSpell = data.optionalLong("crit_rating_spell"),
        speedRating = data.optionalLong("speed_rating"),
        leechRating = data.optionalLong("leech_rating"),
        hasteRatingMelee = data.optionalLong("haste_rating_melee"),
        hasteRatingRanged = data.optionalLong("haste_rating_ranged"),
        hasteRatingSpell = data.optionalLong("haste_rating_spell"),
        avoidanceRating = data.optionalLong("avoidance_rating"),
        masteryRating = data.optionalLong("mastery_rating"),
        versatilityDamageDone = data.optionalLong("versatility_damage_done"),
        versatilityHealingDone = data.optionalLong("versatility_healing_done"),
        versatilityDamageTaken = data.optionalLong("versatility_damage_taken"),
        armor = data.optionalLong("armor"),
        specId = data.optionalString("spec_id"),
        talents = data.optionalTalentEntries("talents"),
        pvpTalents = data.optionalLongList("pvp_talents"),
        gear = data.optionalGearSlots("gear"),
        activeAuras = data.optionalActiveAuras("active_auras"),
    )

    "COMBAT_LOG_VERSION" -> CombatLogVersionEvent(
        formatVersion = data.optionalLong("format_version"),
        advancedLogEnabled = data.optionalBoolean("advanced_log_enabled"),
        buildVersion = data.optionalString("build_version"),
        projectId = data.optionalString("project_id"),
    )

    "PLAYER_REGEN_DISABLED" -> PlayerRegenDisabledEvent
    "PLAYER_REGEN_ENABLED" -> PlayerRegenEnabledEvent
    "UNRECOGNIZED_EVENT" -> UnrecognizedEventEvent(data.requiredString("event_name"))
    "MALFORMED_EVENT" -> MalformedEventEvent(
        reason = data.requiredString("reason"),
        rawBytes = data.requiredIntList("raw_bytes"),
    )

    else -> throw CombatEventDecodeException("Unknown event type: $type")
}

private fun JsonObject.decodeHeader() = CommonHeader(
    sourceGuid = this.optionalString("source_guid"),
    sourceName = this.optionalString("source_name"),
    sourceFlags = this.optionalLong("source_flags"),
    sourceRaidFlags = this.optionalLong("source_raid_flags"),
    destGuid = this.optionalString("dest_guid"),
    destName = this.optionalString("dest_name"),
    destFlags = this.optionalLong("dest_flags"),
    destRaidFlags = this.optionalLong("dest_raid_flags"),
)

private fun JsonObject.decodeSpellPrefix() = SpellPrefix(
    spellId = this.optionalString("spell_id"),
    spellName = this.optionalString("spell_name"),
    spellSchool = this.optionalLong("spell_school"),
)

private fun JsonObject.decodeAdvancedBlock() = AdvancedLoggingBlock(
    unit = optionalString("unit"),
    infoGuid = this.optionalString("info_guid"),
    ownerGuid = this.optionalString("owner_guid"),
    currentHp = this.optionalLong("current_hp"),
    maxHp = this.optionalLong("max_hp"),
    attackPower = this.optionalLong("attack_power"),
    spellPower = this.optionalLong("spell_power"),
    armor = this.optionalLong("armor"),
    absorb = this.optionalLong("absorb"),
    unknown1 = this.optionalLong("unknown_1"),
    unknown2 = this.optionalLong("unknown_2"),
    powerType = this.optionalLong("power_type"),
    currentPower = this.optionalLong("current_power"),
    maxPower = this.optionalLong("max_power"),
    powerCost = this.optionalLong("power_cost"),
    positionX = this.optionalDouble("position_x"),
    positionY = this.optionalDouble("position_y"),
    uiMapId = this.optionalString("ui_map_id"),
    facing = this.optionalDouble("facing"),
    itemLevel = this.optionalLong("item_level"),
)

private fun JsonObject.requiredString(name: String): String =
    (this[name] as? JsonPrimitive)?.takeIf { it.isString }?.content
        ?: throw CombatEventDecodeException("'$name' must be a string")

private fun JsonObject.requiredObject(name: String): JsonObject =
    this[name] as? JsonObject
        ?: throw CombatEventDecodeException("Event data must include object '$name'")

private fun JsonObject.optionalObject(name: String): JsonObject? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonObject -> value
    else -> throw CombatEventDecodeException("'$name' must be an object or null")
}

private fun JsonObject.optionalString(name: String): String? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonPrimitive -> if (value.isString) value.content else throw CombatEventDecodeException(
        "'$name' must be a string or null"
    )

    else -> throw CombatEventDecodeException("'$name' must be a string or null")
}

private fun JsonObject.optionalLong(name: String): Long? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonPrimitive -> if (!value.isString) value.longOrNull
        ?: throw CombatEventDecodeException("'$name' must be an integer or null") else throw CombatEventDecodeException(
        "'$name' must be an integer or null"
    )

    else -> throw CombatEventDecodeException("'$name' must be an integer or null")
}

private fun JsonObject.optionalDouble(name: String): Double? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonPrimitive -> if (!value.isString) value.doubleOrNull
        ?: throw CombatEventDecodeException("'$name' must be a number or null") else throw CombatEventDecodeException(
        "'$name' must be a number or null"
    )

    else -> throw CombatEventDecodeException("'$name' must be a number or null")
}

private fun JsonObject.optionalBoolean(name: String): Boolean? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonPrimitive -> if (!value.isString) value.booleanOrNull
        ?: throw CombatEventDecodeException("'$name' must be a boolean or null") else throw CombatEventDecodeException(
        "'$name' must be a boolean or null"
    )

    else -> throw CombatEventDecodeException("'$name' must be a boolean or null")
}

private fun JsonObject.optionalJsonElement(name: String): JsonElement? =
    this[name]?.takeUnless { it == JsonNull }

private fun JsonObject.requiredIntList(name: String): List<Int> =
    (this[name] as? JsonArray)?.mapIndexed { index, value ->
        val number = (value as? JsonPrimitive)?.takeIf { !it.isString }?.intOrNull
            ?: throw CombatEventDecodeException("'$name[$index]' must be an integer")
        if (number !in 0..255) throw CombatEventDecodeException("'$name[$index]' must be a byte value")
        number
    }
        ?: throw CombatEventDecodeException("'$name' must be an array")

private fun JsonObject.optionalLongList(name: String): List<Long?>? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonArray -> value.longItems(name)
    else -> throw CombatEventDecodeException("'$name' must be an array or null")
}

private fun JsonObject.optionalTalentEntries(name: String): List<TalentEntry>? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonArray -> value.mapIndexed { index, entry ->
        val fields = entry as? JsonArray ?: throw CombatEventDecodeException(
            "'$name[$index]' must be an array"
        )
        if (fields.size != 3) throw CombatEventDecodeException("'$name[$index]' must contain 3 values")
        TalentEntry(
            fields[0].longItemOrNull("$name[$index][0]"),
            fields[1].longItemOrNull("$name[$index][1]"),
            fields[2].longItemOrNull("$name[$index][2]")
        )
    }

    else -> throw CombatEventDecodeException("'$name' must be an array or null")
}

private fun JsonObject.optionalGearSlots(name: String): List<GearSlot>? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonArray -> value.mapIndexed { index, slot ->
        val fields = slot as? JsonArray ?: throw CombatEventDecodeException(
            "'$name[$index]' must be an array"
        )
        if (fields.size != 5) throw CombatEventDecodeException("'$name[$index]' must contain 5 values")
        GearSlot(
            fields[0].longItemOrNull("$name[$index][0]"),
            fields[1].longItemOrNull("$name[$index][1]"),
            fields[2].longArray("$name[$index][2]"),
            fields[3].longArray("$name[$index][3]"),
            fields[4].longArray("$name[$index][4]")
        )
    }

    else -> throw CombatEventDecodeException("'$name' must be an array or null")
}

private fun JsonObject.optionalActiveAuras(name: String): List<ActiveAura>? = when (val value = this[name]) {
    null, JsonNull -> null
    is JsonArray -> value.mapIndexed { index, item ->
        val entry = item as? JsonArray ?: throw CombatEventDecodeException(
            "'$name[$index]' must be an array"
        )
        ActiveAura(
            sourceGuid = entry.getOrNull(0)?.stringItemOrNull("$name[$index][0]"),
            spellId = entry.getOrNull(1)?.stringItemOrNull("$name[$index][1]"),
            remaining = entry.drop(2).mapIndexed { j, el -> el.stringItemOrNull("$name[$index][${j + 2}]") },
        )
    }

    else -> throw CombatEventDecodeException("'$name' must be an array or null")
}

private fun JsonArray.longItems(field: String): List<Long?> =
    mapIndexed { index, value -> value.longItemOrNull("$field[$index]") }

private fun JsonElement.longArray(field: String): List<Long?> =
    (this as? JsonArray)?.longItems(field)
        ?: throw CombatEventDecodeException("'$field' must be an array")

private fun JsonElement.longItemOrNull(field: String): Long? = when (this) {
    JsonNull -> null
    is JsonPrimitive -> if (!isString) longOrNull
        ?: throw CombatEventDecodeException("'$field' must be an integer or null") else throw CombatEventDecodeException(
        "'$field' must be an integer or null"
    )

    else -> throw CombatEventDecodeException("'$field' must be an integer or null")
}

private fun JsonElement.stringItemOrNull(field: String): String? = when (this) {
    JsonNull -> null
    is JsonPrimitive -> content // works for both JSON strings and bare numbers/booleans
    else -> throw CombatEventDecodeException("'$field' in active_auras must be a primitive or null")
}
